export const BODY: string = "\n<p>التشبع هو شدة اللون في صورة: صورة مشبعة جدًا لها ألوان حية وقوية، بينما صورة غير مشبعة تبدو باهتة وناعمة أو رمادية تمامًا.</p>\n<p>إصابة التشبع صحيحًا هي ما يجعل صورة تشعر بالطبيعية: بقليل جدًا، تبدو الصورة مغسولة وبلا حياة، بينما بكثير جدًا يلمع العشب نيونًا ويتحول الجلد إلى برتقالي.</p>\n<p>يشرح هذا الدليل كيف يعمل التشبع وكيف تستخدم المنزلق والإعدادات السريعة جيدًا وكيف تحافظ على ألوان طبيعية: يغطي صورًا شخصية ومناظر وطعامًا ومنتجات وأخطاء تجعل صورًا تبدو مصطنعة.</p>\n<h2 id=\"what-saturation-does\">ماذا يفعل التشبع فعلًا؟</h2>\n<p>التشبع يتحكم في كم ألوان صورة نقية أو رمادية: عند رفعه، يصبح كل لون أقوى وأحيا، بينما عند خفضه يُستنزف اللون نحو الرمادي.</p>\n<p>عند الصفر، تبدو الصورة طبيعية: وعند 100 بالمئة موجبًا، الألوان قوية بقدر ما تستطيع، وعند 100 بالمئة سالبًا، تصبح الصورة أبيض وأسود تمامًا. والتشبع لا يغيّر السطوع ولا التباين كثيرًا: يغيّر فقط كم الألوان تشعر بالشدة، فصورة باهتة قد تصبح حية دون أن تفتّح أو تظلم.</p>\n<p>فكر في التشبع كضبط حجم اللون: رفعه يجعل الألوان أقوى، وخفضه يجعلها أنعم، وتبقى الصورة نفسها تحته.</p>\n<h2 id=\"why-photos-look-dull\">لماذا تخرج الصور باهتة؟</h2>\n<p>الضوء الغائم هو السبب الأكثر شيوعًا لألوان باهتة: سماء مغطاة تبعثر الضوء بالتساوي، ما يغسل الألوان ويترك الصورة تبدو رمادية.</p>\n<p>وكاميرات الهواتف قد تطفئ الألوان أيضًا في ضوء قليل: المستشعر يكافح لالتقاط النطاق اللوني كله، وتخرج الصورة مسطحة أكثر مما بدا المشهد. وصور قديمة ممسوحة تفقد لونًا مع العمر: أصباغ طباعة تبهت عبر عقود، والمسح يُظهر نسخة شاحبة ومغسولة من الأصل.</p>\n<p>ولقطات الشاشة غالبًا تبدو باهتة أيضًا: صورة لشاشة ملتقطة بتوازن أبيض خطأ قد تستنزف اللون من صورة ساطعة غير ذلك.</p>\n<h2 id=\"slider-explained\">منزلق التشبع موضح</h2>\n<p>يمتد منزلق التشبع من 100 سالبًا إلى 100 موجبًا بالمئة، والصفر يعني لا تغيير: تحريكه يمينًا يعزز الألوان، وتحريكه يسارًا يستنزفها.</p>\n<p>الحركات الصغيرة تحدث فرقًا كبيرًا: تغيير 10 إلى 25 بالمئة غالبًا يكفي لإصلاح صورة باهتة، والحركات الأكبر تجعل الألوان تبدو مصطنعة بسرعة. وتعرض الأداة صورتك بزيادة 25 بالمئة فور رفعها: نقطة البداية تلك تعطيك فكرة فورية عن شكل زيادة تشبع معتدلة.</p>\n<p>اسحب المنزلق ببطء وراقب المعاينة: التحديث المباشر يُظهر بالضبط كيف تستجيب الألوان، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة طبيعية.</p>\n<h2 id=\"quick-presets\">إعدادات سريعة للون بنقرة واحدة</h2>\n<p>تشمل الأداة إعدادات سريعة بنقرة واحدة تطبق قيم تشبع شائعة فورًا: طريقة سريعة لتجربة مظاهر مختلفة دون سحب المنزلق.</p>\n<p>تشمل الإعدادات السريعة \"باهت\" بـ40 بالمئة سالبًا و\"تدرج رمادي\" بـ100 بالمئة سالبًا و\"مفرط\" بـ90 بالمئة موجبًا: كل منها يعطي مظهرًا مختلفًا بنقرة واحدة. والإعدادات السريعة نقطة بداية لا إجابة نهائية: انقر واحدًا وراقب المعاينة ثم اضبط بالمنزلق إذا كانت النتيجة قريبة لكنها ليست صحيحة تمامًا.</p>\n<p>ولدفعة صور متشابهة، نفس الإعداد السريع يحافظ على نتائج متسقة: مجموعة مناظر باهتة، كلها معززة بنفس المقدار، تبدو كسلسلة.</p>\n<h2 id=\"muted-vs-grayscale\">باهت أم تدرج رمادي: طريقتان لاستنزاف اللون</h2>\n<p>باهت، بـ40 بالمئة سالبًا، يلطّف الألوان دون إزالتها: تحتفظ الصورة بلمسة من لوحتها، لكن النغمات تشعر بالهدوء والصمت والرصانة.</p>\n<p>وتدرج رمادي، بـ100 بالمئة سالبًا، يزيل كل اللون: تصبح الصورة أبيض وأسود، ويبقى فقط السطوع والتباين لدعم الصورة. وباهت يناسب صورًا شخصية ومناظر ناعمة، حيث لوحة رقيقة تشعر بالأناقة: وتدرج رمادي يناسب مشاهد درامية وعمارة وتصوير شوارع، حيث الشكل يهم أكثر من اللون.</p>\n<p>اختر باهتًا عندما تكون الألوان جزءًا من الصورة لكنها قوية جدًا: واختر تدرج رمادي عندما يشتت اللون عن الشخص وتعمل الصورة أفضل بدونه.</p>\n<h2 id=\"hyper-saturation\">تشبع مفرط: عندما يكون الأكثر كثيرًا</h2>\n<p>مفرط، بـ90 بالمئة موجبًا، يدفع الألوان إلى حدها: يصبح العشب أخضر كهربائيًا والسماوات أزرق عميقًا والصورة كلها تشعر بالشدة والمصطنعة.</p>\n<p>مفرط يناسب حالات محددة قليلة: ملصق أو رسم اجتماعي أو صورة منمقة حيث الألوان اللافتة هي النقطة: ولا يناسب التصوير الطبيعي. وللمناظر، زيادة معتدلة 20 إلى 30 بالمئة غالبًا هي الحد: أبعد من ذلك، يبدو أوراق الشجر نيونًا والسماء مرسومة، ما يكسر الإحساس الطبيعي.</p>\n<p>وإذا بدت صورة مزيفة بعد تعزيزها، اخفض المنزلق 10 بالمئة وراجع مجددًا: تخفيضات صغيرة غالبًا تستعيد المظهر الطبيعي دون فقدان الحيوية.</p>\n<h2 id=\"saturation-and-skin\">التشبع ونغمات البشرة</h2>\n<p>البشرة هي أصعب ما يُشبع صحيحًا: دفعة صغيرة قد تجعل صورة شخصية تبدو صحية، لكن كبيرة تحوّل البشرة إلى برتقالي أو أحمر أو أصفر.</p>\n<p>ابدأ بزيادة صغيرة 10 إلى 15 بالمئة للصور الشخصية: راجع الوجه: يجب أن تبدو البشرة دافئة وطبيعية، لا كأن الشخص قضى وقتًا طويلًا في الشمس. وراقب الخدين والجبهة، اللذين يُظهران التشبع الزائد أولًا: وجه بخدين برتقاليين وجبهة صفراء دُفع بعيدًا جدًا.</p>\n<p>ولصورة شخصية ببشرة باهتة، فتّح قليلًا أولًا ثم أضف دفعة تشبع صغيرة: المزيج يستعيد التوهج الصحي دون النغمة البرتقالية.</p>\n<h2 id=\"saturation-for-landscapes\">التشبع للمناظر الطبيعية</h2>\n<p>المناظر هي الأكثر استفادة من التشبع: دفعة 20 إلى 30 بالمئة تجعل الخضر أغنى والسماوات أعمق والمشهد كله أحيا.</p>\n<p>راقب أوراق الشجر أثناء زيادة التشبع: العشب والأوراق يصبحان نيونًا أولًا، ومنظر بحقول خضراء ساطعة يبدو مصطنعًا. ولغروب أو شروق، دفعة معتدلة تعزز الألوان الدافئة دون جعلها صارخة: يجب أن تبدو السماء غنية، لا كأنها مرسومة.</p>\n<p>ولمنظر بضباب أو غيم، أبقِ التشبع منخفضًا: اللوحة الباهتة جزء من الجو، ودفعة قوية تصارع أجواء المشهد.</p>\n<h2 id=\"saturation-for-food\">التشبع لصور الطعام</h2>\n<p>صور الطعام تحتاج تشبعًا دقيقًا: دفعة صغيرة تجعل الأطباق تبدو طازجة وشهية، بينما كبيرة تجعلها تبدو بلاستيكية ومزيفة.</p>\n<p>استخدم دفعة 10 إلى 20 بالمئة لمعظم الطعام: يجب أن تبدو الألوان غنية وجذابة، بأحمر دافئ وخضر طازجة، لكن أبدًا نيونًا. وراقب الأحمر خاصة: طماطم ولحم وتوت تصبح أحمر غير طبيعي وساطعًا عندما تُشبع أكثر مما يلزم، ما يجعل الطعام يبدو أقل شهية لا أكثر.</p>\n<p>ولصورة طعام ملتقطة بضوء داخلي دافئ، دفعة تشبع صغيرة زائد زيادة سطوع خفيفة تعمل جيدًا: المزيج يستعيد المظهر الطازج الذي أطفأه الضوء الداخلي.</p>\n<h2 id=\"saturation-for-products\">التشبع لصور المنتج</h2>\n<p>صور المنتج تحتاج لونًا دقيقًا، لأن المشتري يتوقع أن يطابق العنصر الصورة: دفعة تشبع تغيّر لون منتج مشكلة لا تحسين.</p>\n<p>استخدم دفعة صغيرة 5 إلى 15 بالمئة للمنتجات، وقارن اللون بالعنصر الحقيقي: يجب أن تطابق الصورة ما سيستلمه المشتري. وأبقِ التشبع متسقًا في الكتالوج كله: متجر بمستويات لون متطابقة يبدو مرتبًا وموثوقًا، بينما مستويات مختلطة تبدو مهملة.</p>\n<p>ولمنتج بلون علامة قوي، كن حذرًا خاصة: دفعة تحرك لون العلامة، حتى قليلًا، قد تربك المشترين وتضر بالثقة.</p>\n<h2 id=\"desaturating-photos\">كيف تستنزف لمظهر باهت وأنيق</h2>\n<p>الاستنزاف خيار إبداعي لا مجرد إصلاح: صورة باهتة، بألوان ناعمة وهادئة، تشعر بالهدوء والأناقة، ما يناسب حفلات زفاف وصورًا شخصية وفنًا.</p>\n<p>استخدم الإعداد السريع \"باهت\"، بـ40 بالمئة سالبًا، لاستنزاف ناعم: تبقى الألوان مرئية لكنها ناعمة، وتكسب الصورة جوًا راقيًا ورصينًا. والاستنزاف يساعد أيضًا عندما تتصادم الألوان: صورة بجسم أحمر ساطع بجانب جسم أخضر ساطع قد تشعر بالفوضى، وإطفاء الاثنين يجلب تناغمًا.</p>\n<p>ولمظهر مستنزف تمامًا، استخدم \"تدرج رمادي\" بـ100 بالمئة سالبًا: تصبح الصورة أبيض وأسود، ما يناسب مشاهد درامية وصورًا شخصية خالدة.</p>\n<h2 id=\"saturation-and-brightness\">التشبع والسطوع والضوء المدرك</h2>\n<p>محرر التشبع يحافظ على السطوع المدرك أثناء تغيير الألوان: ذلك يعني أن دفعة لا تجعل الصورة تشعر بأنها أفتح أو أظلم، فقط أكثر لونًا.</p>\n<p>هذا مهم لأن محررين آخرين قد يغيّرون السطوع عندما يغيّرون التشبع: صورة تفتّح مع ازدياد لونها أصعب للحكم عليها. ولصورة باهتة وداكنة، فتّح أولًا ثم أضف تشبعًا: الترتيب مهم، لأن صورة داكنة بألوان معززة تبقى تبدو داكنة، فقط بنغمات أقوى.</p>\n<p>ولصورة فاتحة ومغسولة، أضف تشبعًا دون مزيد من التفتيح: الألوان تكسب غنى بينما يبقى السطوع حيث هو.</p>\n<h2 id=\"formats-and-export\">الصيغ والتصدير</h2>\n<p>تقبل الأداة صيغ صور شائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 MB: وتستطيع التصدير كـJPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير كـPNG أو WebP يحافظ على شفافية الصورة الأساسية: إذا كان مصدرك ملصق PNG شفافًا، فالتصدير المعدل بالتشبع يحافظ على المناطق الشفافة سليمة. وللصور، JPG بضبط جودة عالية يعمل جيدًا: التشبع لا يضيف كثيرًا إلى حجم الملف، فالتصدير يبقى قريبًا من الوزن الأصلي.</p>\n<p>ويظهر ضبط الجودة لتصديرات JPG وWebP، ويُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: تعديل دون رفع أي شيء</h2>\n<p>كل تعديل تشبع يحدث في متصفحك: صورك لا تُرفع أبدًا إلى خادم، وهو أمر مهم عندما تكون الصور شخصية أو صورًا عائلية أو عمل عملاء.</p>\n<p>هذه ميزة حقيقية مقابل محررات السحابة: صورة عائلية أو صورة منتج خاصة لا يجب أن تسافر إلى خادم لا تستطيع رؤيته، فقط لتعزيز ألوانها. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة معدلة بالتشبع منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>احتفظ بالصورة الأصلية دون تعديل: بمجرد أن يُسطّح تغيير تشبع في تصدير، لا يمكن التراجع عنه من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند ضبط التشبع</h2>\n<p>أكثر خطأ شيوعًا تعزيز أكثر مما يلزم: صورة مدفوعة إلى 60 أو 90 بالمئة موجبًا تبدو مصطنعة، بعشب نيون وبشرة برتقالية وسماء مرسومة.</p>\n<p>خطأ آخر تشبيع صورة حية أصلًا: غروب ملون أو زهرة ساطعة تحتاج دفعة قليلة أو لا شيء، وإضافة المزيد تجعلها صارخة فقط. وينسى الناس أيضًا مراجعة البشرة: دفعة منظر تبدو جيدة في المشهد قد تحوّل الأشخاص في الصورة إلى برتقالي، فراجع الوجوه دائمًا.</p>\n<p>وأخيرًا، لا تضبط نفس JPG مرة بعد مرة: كل حفظ يضيف ضررًا، فعد دائمًا إلى الملف الأصلي عندما تريد مستوى تشبع مختلفًا.</p>\n<h2 id=\"saturation-workflow\">سير عمل للون طبيعي</h2>\n<p>ابدأ بالملف الأصلي وقرر إن كانت الصورة باهتة أو حية أو بلون صحيح: باهتة تحتاج دفعة، وحية لا تحتاج شيئًا، وصارخة تحتاج إطفاءً.</p>\n<p>طبّق التشبع ثم راجع المعاينة بالحجم الكامل: اقترب من البشرة وأوراق الشجر والسماء، وتأكد من أن لا لون يبدو مصطنعًا. وأضف سطوعًا أو تباينًا إذا احتاجتهما الصورة، بعد تثبيت التشبع: تغيير اللون قد يجعل الصورة تشعر بالاختلاف، فراجع النغمات مجددًا.</p>\n<p>صدّر بضبط جودة عالية وراجع النتيجة على شاشة ثانية إن استطعت: الألوان تبدو مختلفة على شاشات مختلفة، ومراجعة ثانية تكشف مفاجآت.</p>\n<h2 id=\"saturation-for-weddings\">التشبع لصور الزفاف</h2>\n<p>صور الزفاف تحتاج لونًا ناعمًا وطبيعيًا: دفعة تشبع لطيفة 10 إلى 15 بالمئة تجعل الزهور أغنى والفساتين أكثر إشراقًا، دون أن تبدو البشرة برتقالية.</p>\n<p>راقب الفستان الأبيض أثناء تعزيز التشبع: فستان أبيض يجب أن يبقى أبيض، ودفعة قوية قد تصبغه أصفر أو ورديًا، ما يبدو سيئًا في ألبوم زفاف. ولحفلات زفاف خارجية، دفعة معتدلة تعزز الخضر والسماء دون إطفاء الزوجين: يجب أن يبقى الأشخاص هم التركيز لا الألوان حولهم.</p>\n<p>وأبقِ التشبع متسقًا في مجموعة الزفاف كلها: ألبوم بمستويات لون متطابقة يبدو احترافيًا، بينما مستويات مختلطة تجعل اليوم يشعر بالتفكك.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-taadil-tashabbu-as-sura/\">كيف تضبط تشبع صورة</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/tashabbu-vs-hayawiyya/\">التشبع أم الحيوية: تعديل لون طبيعي</a>، ولإضافة مظهر متسق بمرشحات جرّب <a href=\"/ar/murashshahat-as-suwar/\">مرشحات الصور</a>. وجرّب كل ضبط مجانًا في <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم تشبعًا يجب أن أضيف إلى صورة باهتة؟","answer":"ابدأ بـ10 إلى 25 بالمئة وراجع المعاينة: معظم الصور الباهتة تحتاج دفعة صغيرة فقط، والحركات الأكبر تجعل الألوان تبدو مصطنعة بسرعة. وزد بخطوات صغيرة وتوقف عندما تبدو الصورة حية دون أن تبدو مزيفة."},{"question":"لماذا يبدو بورتريه برتقاليًا بعد تعزيز التشبع؟","answer":"البشرة تُظهر التشبع الزائد أولًا، متحولة إلى برتقالي أو أحمر أو أصفر عندما يكون المنزلق مرتفعًا جدًا: اخفض التشبع حتى تبدو البشرة دافئة وطبيعية. وللصور الشخصية، دفعة صغيرة 10 إلى 15 بالمئة تكفي عادة."},{"question":"ما الفرق بين باهت وتدرج رمادي؟","answer":"باهت، بـ40 بالمئة سالبًا، يلطّف الألوان دون إزالتها، محافظًا على لمسة من اللوحة لمظهر هادئ وأنيق: وتدرج رمادي، بـ100 بالمئة سالبًا، يزيل كل اللون ويحوّل الصورة إلى أبيض وأسود."},{"question":"هل يستطيع التشبع إصلاح صورة ملتقطة بضوء سيئ؟","answer":"جزئيًا: التشبع يستعيد شدة اللون، لكنه لا يستطيع إصلاح صورة داكنة جدًا أو مسطحة جدًا. وفتّح الصورة أولًا ثم أضف تشبعًا، وأضف تباينًا إذا بدت الصورة مسطحة بعدها."},{"question":"هل تغيير التشبع يؤثر في سطوع صورتي؟","answer":"هذا المحرر يحافظ على السطوع المدرك أثناء تغيير الألوان، فدفعة تجعل الصورة أكثر حيوية دون أن تجعلها تشعر بأنها أفتح أو أظلم: ذلك يجعل الحكم على تغيير اللون وحده أسهل."},{"question":"هل تعديل تشبع صورة شخصية في أداة متصفح آمن؟","answer":"نعم، لأن كل المعالجة تحدث محليًا في متصفحك ولا يُرفع شيء إلى خادم: وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير. واحتفظ بالملف الأصلي إذا أردت تجربة مستوى تشبع آخر."}];
